import { Component, Host, SkipSelf, OnInit }	from '@angular/core';
import { ControlContainer }	from '@angular/forms';
import { EspdFormGroup } from 'espd-common/forms/api';
import { MessageService } from 'espd-common/i18n';

@Component({
    selector: 'espd-form-invalid-alert',
    templateUrl: 'form-invalid-alert.component.html',
    standalone: false
})
export class FormInvalidAlertComponent implements OnInit {
	public form?: EspdFormGroup;

	private parent: ControlContainer;

	constructor(@Host() @SkipSelf() parent: ControlContainer, public messageService: MessageService) {
		this.parent = parent;
	}

	public ngOnInit(): void {
		this.form = this.parent.control?.root as EspdFormGroup;
	}
}