import { CommonModule } from '@angular/common';
import { ModuleWithProviders, NgModule } from '@angular/core';
import { ButtonComponent } from 'espd-common/button';
import { MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { AlertListComponent } from './alert-list.component';
import { AlertListService } from './alert-list.service';
import { AlertComponent } from './alert.component';
import { FormInvalidAlertComponent } from './form-invalid-alert.component';
import { InlineAlertComponent } from './inline-alert.component';

@NgModule({
	imports: [
		CommonModule,
		ButtonComponent,
		IconDirective,
		MessageModule
	],
	declarations: [
		AlertComponent,
		InlineAlertComponent,
		AlertListComponent,
		FormInvalidAlertComponent
	],
	exports: [
		AlertComponent,
		InlineAlertComponent,
		AlertListComponent,
		FormInvalidAlertComponent
	]
})
export class AlertModule {
	public static forRoot(): ModuleWithProviders<AlertModule> {
		return { ngModule: AlertModule, providers: [AlertListService] };
	}
}